```sparql
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorName ?birthDate
WHERE {
  VALUES ?film { dbr:The_Mate_of_the_Sally_Ann dbr:The_Legend_of_Hercules }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?dir1 . }
  OPTIONAL { ?film dbo:director ?dir2 . }
  BIND (COALESCE(?dir1, ?dir2) AS ?director)

  # director name (prefer dbp:name)
  OPTIONAL { ?director dbp:name ?name1 . }
  OPTIONAL { ?director rdfs:label ?name2 . FILTER (lang(?name2) = "en") }
  BIND (COALESCE(?name1, ?name2) AS ?directorName)

  # director birth date (prefer dbp:birthDate)
  OPTIONAL { ?director dbp:birthDate ?bdate1 . }
  OPTIONAL { ?director dbo:birthDate ?bdate2 . }
  BIND (COALESCE(?bdate1, ?bdate2) AS ?birthDate)

  # film label (optional, for readability)
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (lang(?filmLabel) = "en") }
}
LIMIT 100
